/**
 * The parts of a text that match, marked (`design/components/highlight.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/highlight.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, derived, highlightRuns, useMember, type Each } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/highlight.module.css'

/** The parts of a text that match, marked: the inputs it takes, by the React member's prop names. */
export interface HighlightProps {
  /**
   * The locale that folds case for `query`, the page's; omitted, the runtime's.
   */
  locale?: string
  /**
   * One term or several, each marked wherever it occurs, as written and never as a pattern, with
   * case folded by `locale`. Each term is trimmed, and an empty one marks nothing.
   */
  query?: string | string[]
  /**
   * `[start, end]` offsets into `text`, end exclusive, in JavaScript's string offsets (UTF-16
   * code units), for an app whose search engine says where its matches are. With `ranges`,
   * `query` is not used. Ranges that overlap or touch are one mark, and a range is cut at the
   * text's end.
   */
  ranges?: [number, number][]
  /**
   * The text, drawn whole.
   */
  text: string
}

/** The parts of a text that match, marked. */
@Component({
  selector: 'pm-highlight',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `@if (e1()) {<span
[attr.class]="e2()"
data-member="highlight"
>@for (run of e3(); track e4($index); let index = $index) {@if (e5(run)) {<mark
[attr.class]="e6(run)"
role="presentation"
>{{ e7(run) }}</mark>} @else {{{ e8(run) }}}}</span>}`,
})
export class Highlight {
  /**
   * The locale that folds case for `query`, the page's; omitted, the runtime's.
   */
  readonly locale = input<HighlightProps['locale']>(undefined)
  /**
   * One term or several, each marked wherever it occurs, as written and never as a pattern, with
   * case folded by `locale`. Each term is trimmed, and an empty one marks nothing.
   */
  readonly query = input<HighlightProps['query']>(undefined)
  /**
   * `[start, end]` offsets into `text`, end exclusive, in JavaScript's string offsets (UTF-16
   * code units), for an app whose search engine says where its matches are. With `ranges`,
   * `query` is not used. Ranges that overlap or touch are one mark, and a range is cut at the
   * text's end.
   */
  readonly ranges = input<HighlightProps['ranges']>(undefined)
  /**
   * The text, drawn whole.
   */
  readonly text = input.required<HighlightProps['text']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      locale: () => this.locale(),
      query: () => this.query(),
      ranges: () => this.ranges(),
      text: () => this.text(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly runs = derived(() =>
    highlightRuns(this.$p.text, {
      query: this.$p.query,
      ranges: this.$p.ranges,
      locale: this.$p.locale,
    }),
  )

  protected e1() {
    return this.runs.value.length > 0
  }

  protected e2() {
    if (!(this.runs.value.length > 0)) return undefined as never
    return styles.highlight
  }

  e3() {
    if (!(this.runs.value.length > 0)) return undefined as never
    return this.runs.value
  }

  protected e4(index: number) {
    return index
  }

  protected e5(run: Each<ReturnType<Highlight['e3']>>) {
    if (!(this.runs.value.length > 0)) return undefined as never
    return run.marked
  }

  protected e6(run: Each<ReturnType<Highlight['e3']>>) {
    if (!(this.runs.value.length > 0)) return undefined as never
    if (!run.marked) return undefined as never
    return styles.mark
  }

  protected e7(run: Each<ReturnType<Highlight['e3']>>) {
    if (!(this.runs.value.length > 0)) return undefined as never
    if (!run.marked) return undefined as never
    return run.text
  }

  protected e8(run: Each<ReturnType<Highlight['e3']>>) {
    if (!(this.runs.value.length > 0)) return undefined as never
    if (run.marked) return undefined as never
    return run.text
  }
}
